s:
/* =============================================================
   Shutterhaus Visuals — rebuilt from the Van André Rensburg reference
   Tokens first, then site chrome, gallery, lightbox, admin.
   ============================================================= */

:root {
  --ink: #111;
  /* Inactive nav was #8c8c8c — only 3.36:1 on white, failing WCAG AA at 12px.
     #6b6b6b is 5.3:1 and still reads as "quiet next to" the active item, so the
     hierarchy survives without the contrast failing. */
  --grey: #6b6b6b;
  --line: #e6e6e6;
  --paper: #fff;
  --dim: #6d6d6d;

  --pad: 26px;          /* outer page gutter */
  --gut: 14px;          /* gap between columns/images */
  --head: 118px;        /* header height */

  /* iPhone safe-area insets, aliased once so no rule has to spell out the
     max() fallback itself. `env(safe-area-inset-*)` is 0 on every browser
     that does not understand it and on every desktop, so wrapping it in
     max(<fallback>, env(...)) means these are a plain 0 on the machines
     this was written on and grow to 59px/34px/0px only on a notched
     device. A bare `env()` is technically valid CSS but invalid in
     browsers without support, which drops the whole declaration; max()
     keeps the fallback and the inset in one property.
     Values are read from the iPhone 16: 59px top (Dynamic Island band),
     34px bottom (home indicator), 0 left/right in portrait. */
  --sat: max(0px, env(safe-area-inset-top));
  --sab: max(0px, env(safe-area-inset-bottom));
  --sal: max(0px, env(safe-area-inset-left));
  --sar: max(0px, env(safe-area-inset-right));

  --font-display: "Archivo Black", "Helvetica Neue", Arial, sans-serif;
  --font-body: "Inter", -apple-system, "Segoe UI", Helvetica, Arial, sans-serif;
  /* System monospace on purpose: no extra font request, and it reads as
     "spec sheet" next to the Archivo display type. Used for metadata only. */
  --font-mono: ui-monospace, "SF Mono", Menlo, Consolas, "Liberation Mono", monospace;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  /* Kept, because .shell { min-height: 100% } and the sticky header both
     resolve their percentages against it. Dropping it in the process of
     adding the insets was a regression, not a simplification. */
  height: 100%;
  /* Left/right insets live here, once, rather than on .main and every full-bleed
     section. A body inset shrinks the ICB, so `position: fixed` chrome and any
     `100vw` element are already clamped to the safe width, and the
     full-bleed rules that cancel `var(--pad)` with a negative margin
     (.hero, .hcta, .invest) only cancel the gutter — not the inset — which is
     exactly the intent: those sections are meant to reach the screen edge but
     never under a rounded corner in landscape. Bottom inset likewise keeps the
     last row of a page clear of the home indicator; `height: 100%` above is
     left alone because the box-sizing below makes it content height, and the
     padding-bottom is what actually reserves the space. */
  padding-left: var(--sal);
  padding-right: var(--sar);
  padding-bottom: var(--sab);
  background: var(--paper);
  color: var(--ink);
  font-family: var(--font-body);
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }
img { display: block; max-width: 100%; }
.icon { display: block; }

/* ---------------------------------------------------------- header */

.shell { min-height: 100%; }

.site-header {
  /* STICKY, fixed 2026-10-02. This was `position: relative`, which means the
     header scrolls away with the document: on #/services the audit measured the
     burger at top: -3105px, so reaching the menu meant scrolling back 3124px.
     The burger is the ONLY navigation on a phone, so a page that scrolls it out
     of reach is a page you can only navigate by scrolling back to the top.
     `sticky` keeps it in the document flow (so the hero on the home route still
     starts at the very top) while pinning it to the viewport as you scroll. */
  position: sticky;
  top: 0;
  /* Above the hero photograph (z-index 5) and the nav drawer, or the header
     would slide under the drawer instead of carrying it. */
  z-index: 6;
  /* The mobile nav drawer is absolutely positioned against this. */
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  /* The top inset is added to --head, not swapped for it, so the bar keeps
     its designed height AND gains clearance for the Dynamic Island. With a
     fixed `height` and a padding-top the content would just be squeezed
     upward and the burger would sit at the very top of the box, which is
     precisely the y=18px defect. box-sizing is border-box (set above), so
     the total is --head + --sat and the 20px row of content lands below
     the island. */
  height: calc(var(--head) + var(--sat));
  padding: var(--sat) var(--pad) 0;
  gap: 20px;
  /* Opaque, because it now sits over scrolling content and a transparent
     header would let photos run under the wordmark. The home route overrides
     this with its own scrim in .shell--over. */
  background: var(--paper);
}

/* Logo lockup: small word inline, big word wrapping onto a second line. */
.logo {
  /* "SHUTTERHAUS" on the first line, "VISUALS" on the second (see
     .logo-lg--b). The tap-target pass added a second .logo rule with
     `display: inline-flex` to give it a 44px box — inline-flex lays the two
     spans out as ROW flex items, which silently collapsed the wordmark from
     two stacked lines into one line. `inline-block` is what preserves the
     stacked layout; the min-height below is enough to size the target. */
  display: inline-block;
  justify-self: start;
  line-height: 0.86;
  letter-spacing: -0.02em;
  text-transform: uppercase;
  /* Padding, NOT min-height. The header is a centred grid, so a min-height
     taller than the logo's own content re-centres it and pushes the small top
     word to top: -3px at 390px — off-screen, so "SHUTTERHAUS" disappears and
     only "VISUALS" shows. Padding grows the tap box without changing the
     layout box the grid measures. */
  padding: 11px 0;
}
.logo-row { display: flex; align-items: baseline; gap: 6px; }
/* Both words are tracked out, and the small one is sized so its optical width
   MATCHES the big word below — that shared measure is what makes it read as a
   single considered lockup rather than a caption stacked on a title. The
   reference does exactly this in a spaced serif. Archivo Black is far wider
   per glyph, so the small word needs fewer characters-worth of tracking to
   land on the same width. */
.logo-sm {
  font-family: var(--font-display);
  font-size: 11px;
  letter-spacing: 0.34em;
  transform: translateY(-0.5em);
}
.logo-lg {
  font-family: var(--font-display);
  font-size: 27px;
  /* Display type at this size needs the tracking pulled IN, not out — a wide
     gap between SHUTTER/HAUS reads as two words. */
  letter-spacing: -0.005em;
  font-weight: 400;
}
.logo-lg--b { display: block; }

/* Nav sits centre-left, matching the reference's offset placement. */
.site-nav { display: flex; gap: 30px; }

/* The reference collapses the nav behind a hamburger below 760px. Hidden on
   desktop entirely so it can never be tabbed to when it's not on screen. */
.burger {
  display: none;
  justify-self: end;
  width: 44px;
  height: 44px;
  padding: 0;
  background: none;
  border: 0;
  cursor: pointer;
  align-items: center;
  justify-content: center;
}
.burger__bars { display: block; width: 20px; }
.burger__bars i {
  display: block;
  height: 1px;
  background: var(--ink);
  transition: transform 0.18s ease;
}
.burger__bars i:first-child { margin-bottom: 5px; }
.burger[aria-expanded="true"] .burger__bars i:first-child { transform: translateY(3px) rotate(45deg); }
.burger[aria-expanded="true"] .burger__bars i:last-child { transform: translateY(-3px) rotate(-45deg); }
.burger:focus-visible { outline: 1px solid var(--ink); outline-offset: 2px; }
.nav-link {
  font-size: 12px;
  color: var(--grey);
  letter-spacing: 0.01em;
  /* min-height rather than padding alone, so the 44px tap target holds at
     every width — a tablet is a touch device too, and the first mobile pass
     only fixed this inside the 640px query, leaving 768/1024/1440 at 18px. */
  display: inline-flex;
  align-items: center;
  min-height: 44px;
  border-bottom: 1px solid transparent;
  transition: color 0.15s;
}
.nav-link:hover { color: var(--ink); }
.nav-link.is-active { color: var(--ink); border-bottom-color: var(--ink); }

.site-social { display: flex; gap: 16px; justify-self: end; }
.social {
  color: var(--ink);
  opacity: 0.85;
  transition: opacity 0.15s;
  /* Same 44px floor as the nav, at every width. Padding (not a negative
     margin) is what sizes the target, and the flex gap absorbs the growth. */
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 44px;
  min-height: 44px;
}
.social:hover { opacity: 0.5; }

/* --------------------------------------------------------- gallery */

.main { padding: 0 var(--pad) var(--pad); }

.grid {
  display: grid;
  grid-template-columns: repeat(var(--cols, 3), 1fr);
  gap: var(--gut);
  align-items: start;
}
.grid[data-cols="3"] { --cols: 3; }
.grid[data-cols="2"] { --cols: 2; }
.grid[data-cols="1"] { --cols: 1; }

/* Each column scrolls on its own — the reference's signature behaviour. */
.col {
  display: flex;
  flex-direction: column;
  gap: var(--gut);
  max-height: calc(100vh - var(--head) - var(--pad));
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-width: none;
}
.col::-webkit-scrollbar { display: none; }

/* THE SQUISH BUG.
   A flex column's default `align-items` is `stretch`, so every <figure> was
   forced to the height of the tallest one in that column. `.cell img` has
   `height: auto`, which then resolved against that stretched box and changed
   the rendered aspect ratio — a 1440x1800 portrait displayed as a 453x453
   SQUARE. Alwin spotted it on a PC; every portrait in the set was distorted.

   `flex: none` stops the item from being stretched at all, so each figure
   keeps its intrinsic height and the photo keeps its real proportions. */
.cell { margin: 0; flex: none; }
/* The <picture> wrapper is the direct child now, so it has to be the block
   that fills the cell; the img inside it then fills that. */
.cell picture { display: block; }
.cell img {
  width: 100%;
  height: auto;
  /* Placeholder grey flashed on every not-yet-loaded frame. On a phone that
     is most of the second screen, so it read as broken rather than loading. */
  background: #f4f4f4;
  cursor: zoom-in;
  transition: opacity 0.25s;
}
/* Fade in on decode so a slow frame never pops in at full contrast. */
.cell img:not(.is-loaded) { opacity: 0; }
.cell img.is-loaded { opacity: 1; }
/* Only dim a frame that has actually loaded, and only where hover exists —
   :hover never fires on touch, and an un-fired rule would leave the frame
   stuck at the opacity below. */
@media (hover: hover) {
  .cell img.is-loaded:hover { opacity: 0.92; }
}
.cell figcaption {
  font-size: 11px;
  color: var(--dim);
  padding-top: 6px;
}

/* Monochrome at rest, full colour on hover — Alwin wants this back: "I liked
 * having the black and white then on hover shows image as uploaded."
 *
 * CRITICAL: this is a DISPLAY filter only. The files on disk and in Supabase
 * are never processed, re-encoded, or filtered at upload — the JPEG bytes are
 * exactly what came out of the camera. CSS `filter` never rewrites a file; it
 * is composited at paint time and gone the moment the rule is removed. So the
 * original upload survives untouched and the site can change its mind later.
 * Do NOT "optimise" this into a build step — that would be lossy and
 * irreversible, and it is exactly what Alwin is guarding against.
 *
 * THE BASE TREATMENT IS NOT HOVER-GATED — that was the bug, fixed 2026-10-02.
 *
 * The whole rule used to live inside `@media (hover: hover)`, on the reasoning
 * that `:hover` never fires on touch so an unwrapped rule would leave frames
 * "stuck grey on a phone". The consequence was the opposite and far worse: a
 * touch device never matches `(hover: hover)` AT ALL, so the *base* rule was
 * skipped too and the brand's monochrome was off on every phone. Verified on
 * the live site with touch emulation on: `matchMedia('(hover: hover)')` is
 * false, `getComputedStyle(img).filter` is `none` on 30 of 30 portfolio images
 * and 7 of 7 home images, and 25 of the 50 source frames are genuinely in
 * colour. Same site, two different brands depending on the device.
 *
 * So: the BASE (monochrome) is unconditional; only the hover REVEAL is gated,
 * because a reveal is a pointer affordance and there is no pointer to reveal to
 * on a phone. That is the intent the original comment was reaching for. */
.shell.is-bw .cell img { filter: grayscale(1) contrast(1.06); transition: filter 260ms ease; }

@media (hover: hover) {
  .shell.is-bw .cell img:hover,
  .shell.is-bw .cell picture:hover img { filter: grayscale(0) contrast(1); }
}

/* --------------------------------------------------------- contact */

.contact {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  padding: 40px 0 80px;
  max-width: 1100px;
}
/* The reference photograph beside the form.
 *
 * `.contact__fig` had NO rule anywhere — the same class of omission as .cico.
 * The markup sets an inline `aspect-ratio` on the <img>, so the figure reserved
 * a box, but nothing constrained the image itself, and on a phone — where
 * `.contact` collapses to one column and the figure drops BELOW the form — it
 * reserved ~411px and often painted blank, being `loading="lazy"` and not yet in
 * the viewport. Measured at 390px: 531px of blank space below the last line of
 * the contact details.
 *
 * On desktop it is a deliberate half-width column, so it keeps its ratio and is
 * cropped only if that ratio is wrong. On a phone it is decoration behind a form
 * and must not push the page from 1.8 screens to 3. */
.contact__fig {
  position: relative;
  overflow: hidden;
}
.contact__fig img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}
@media (max-width: 760px) {
  .contact__fig { max-height: 38vh; }
}

.contact__h {
  font-family: var(--font-display);
  font-size: 40px;
  letter-spacing: -0.03em;
  text-transform: uppercase;
  margin: 0 0 18px;
  line-height: 0.9;
}
.contact__p { font-size: 14px; line-height: 1.6; color: var(--dim); max-width: 42ch; }
.contact__list { list-style: none; margin: 30px 0 0; padding: 0; font-size: 14px; }
/* Each item is an icon plus a label, side by side. Without `display:flex` the
   <svg> and the <span> stack as blocks, and because the svg has no intrinsic
   size it expands to fill the line — which is what happened. */
.contact__list li {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 12px;
}

/* THE RULE THAT WAS MISSING.
 *
 * `icon()` in pages-more.ts emits <svg class="cico" viewBox="0 0 24 24">, with
 * a comment calling them "tiny inline glyphs". There was never a `.cico` rule in
 * any stylesheet, so the svg had no width and no height: a replaced element with
 * only a viewBox sizes itself to 100% x 100% of its containing block.
 *
 * Measured on the contact page at 390px, before this rule existed:
 *     .contact__list height = 1616px   (four items, mostly whitespace)
 * The pin filled a whole screen, then the envelope, then the phone, then the
 * WhatsApp glyph — each bigger than the text beside it. The contact details
 * that the page exists to show were pushed off the bottom of a 3-screen page.
 *
 * `width/height` with `flex: none` fixes it, and `flex: none` matters because a
 * flex item would otherwise be allowed to shrink below its specified size. */
.cico {
  flex: none;
  width: 18px;
  height: 18px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.4;
  stroke-linecap: round;
  stroke-linejoin: round;
  /* Baseline alignment, so the glyph sits on the text's baseline rather than
   * floating in the middle of the line box. */
  align-self: center;
}

/* Filled variant, for glyphs that are silhouettes rather than outlines. The
   WhatsApp mark is illegible as a hairline outline at 18px — it collapses into a
   tangle — so it is drawn solid instead. */
.cico--fill {
  fill: currentColor;
  stroke: none;
}
/* These are the primary contact actions — tap-to-call, tap-to-email,
   tap-to-WhatsApp. At 20px tall they were the easiest thing on the page to
   miss with a thumb, so the link is padded out to a real target and the
   underline is kept to preserve the reference's look. */
.contact__list a {
  display: inline-block;
  min-height: 44px;
  line-height: 44px;
  border-bottom: 1px solid var(--line);
}
.contact__list a:hover { border-bottom-color: var(--ink); }
.dim { color: var(--dim); }

.cform { display: flex; flex-direction: column; gap: 16px; }
.cform label {
  display: flex;
  flex-direction: column;
  gap: 6px;
  font-size: 11px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--dim);
}
.cform input,
.cform select,
.cform textarea {
  font-family: var(--font-body);
  /* 16px on touch: anything smaller makes iOS Safari zoom the page on focus,
     which is its own "the site jumped" complaint. */
  font-size: 16px;
  color: var(--ink);
  /* min-height, not just padding: the 44px tap minimum has to hold on tablet
     and desktop too, not only inside the 640px media query. */
  min-height: 44px;
  padding: 10px 12px;
  border: 1px solid var(--line);
  background: #fff;
  border-radius: 0;
  width: 100%;
}
.cform input:focus,
.cform select:focus,
.cform textarea:focus { outline: none; border-color: var(--ink); }
.cform button {
  font-family: var(--font-body);
  font-size: 12px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  min-height: 48px;
  padding: 13px 18px;
  background: var(--ink);
  color: #fff;
  border: 0;
  cursor: pointer;
  align-self: flex-start;
}
.cform button:hover { background: #333; }
.cform__note { font-size: 12px; min-height: 1em; margin: 0; }

.empty { padding: 60px 0; }
.empty p { margin: 0 0 6px; font-size: 14px; }
.empty a { border-bottom: 1px solid var(--ink); }

/* -------------------------------------------------------- lightbox */

.lb {
  position: fixed;
  inset: 0;
  /* Fully opaque. At 0.96 the page behind stayed faintly visible through the
     backdrop — the header, the nav and the neighbouring thumbnails all ghosted
     through behind the photograph, which reads as a rendering bug rather than
     as a deliberate scrim. A photo viewer wants the photo and nothing else. */
  background: #0c0c0c;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 100;
}
.lb[hidden] { display: none; }
.lb__img { max-width: 92vw; max-height: 86vh; object-fit: contain; }
.lb__cap {
  position: absolute;
  /* 18px + the home-indicator inset. The caption was measured at 18px from
     the bottom of the viewport, which on an iPhone 16 is inside the 34px
     home-indicator band — the swipe target sits on top of the caption. */
  bottom: calc(18px + var(--sab));
  left: 0;
  right: 0;
  text-align: center;
  color: #fff;
  font-size: 12px;
  opacity: 0.75;
  margin: 0;
  padding: 0 20px;
}
.lb__x,
.lb__nav {
  position: absolute;
  background: none;
  border: 0;
  color: #fff;
  cursor: pointer;
  font-size: 30px;
  line-height: 1;
  opacity: 0.7;
  padding: 10px 16px;
}
/* The audit measured this close button at y=18px on an iPhone 16, which is
   inside the 59px Dynamic Island band: the pill is drawn over the island and
   part of the tap target is unreachable. top is 12px + the top inset, and the
   side insets join it so the control stays inside the rounded corners in
   landscape, where the island moves to a left or right inset. */
.lb__x { top: calc(12px + var(--sat)); right: calc(18px + var(--sar)); font-size: 34px; }
.lb__nav--p { left: calc(14px + var(--sal)); }
.lb__nav--n { right: calc(14px + var(--sar)); }
.lb__x:hover, .lb__nav:hover { opacity: 1; }

/* Each control holds a glyph AND a word. Glyphs by default (the home page's
   lightbox, which is locked); words only when opened from the portfolio wall. */
.lb__t { display: none; }
.lb--wall .lb__g { display: none; }
.lb--wall .lb__t { display: inline; }
.lb--wall .lb__x,
.lb--wall .lb__nav {
  font: 11px/1 var(--font-mono);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  opacity: 0.9;
  min-height: 44px;
  padding: 0 16px;
}
.lb--wall .lb__x { top: 18px; right: 22px; font-size: 11px; }
/* "02 / 50" counter instead of the alt text, in the same mono voice. */
.lb--wall .lb__cap {
  font: 11px/1 var(--font-mono);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  opacity: 0.85;
  bottom: 22px;
}

/* =============================================================
   ADMIN
   ============================================================= */

body.adm-body { background: #f6f6f6; }

.adm { min-height: 100vh; }

.adm__bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 14px 22px;
  background: #fff;
  border-bottom: 1px solid var(--line);
  position: sticky;
  top: 0;
  z-index: 10;
}
.adm__logo {
  font-family: var(--font-display);
  font-size: 14px;
  letter-spacing: -0.01em;
  text-transform: uppercase;
}
.adm__tabs { display: flex; gap: 4px; }
.adm__tab {
  font-family: var(--font-body);
  font-size: 12px;
  padding: 7px 13px;
  background: none;
  border: 0;
  border-radius: 999px;
  color: var(--dim);
  cursor: pointer;
}
.adm__tab:hover { background: #f0f0f0; }
.adm__tab.is-on { background: var(--ink); color: #fff; }
.adm__right { display: flex; align-items: center; gap: 14px; }
.adm__who { font-size: 11px; color: var(--dim); }
.adm__link, .adm__out {
  font-size: 11px;
  color: var(--dim);
  background: none;
  border: 0;
  cursor: pointer;
  padding: 0;
  font-family: var(--font-body);
}
.adm__link:hover, .adm__out:hover { color: var(--ink); }

.adm__body { padding: 22px; max-width: 1300px; margin: 0 auto; }
.pad { font-size: 13px; line-height: 1.7; max-width: 68ch; }
.pad--dim { color: var(--dim); font-size: 12px; }
.lnk { border-bottom: 1px solid var(--ink); }

code {
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 0.92em;
  background: #ececec;
  padding: 1px 5px;
}

/* login gate */
.gate { min-height: 100vh; display: grid; place-items: center; background: #f6f6f6; }
.gate__card {
  background: #fff;
  border: 1px solid var(--line);
  padding: 40px;
  max-width: 400px;
  width: calc(100% - 40px);
  text-align: center;
}
.gate__h {
  font-family: var(--font-display);
  font-size: 30px;
  text-transform: uppercase;
  letter-spacing: -0.02em;
  margin: 0 0 8px;
}
.gate__p { font-size: 13px; color: var(--dim); margin: 0 0 22px; line-height: 1.6; }
.gate__err {
  font-size: 12px;
  color: #b3261e;
  background: #fdeceb;
  padding: 8px 10px;
  margin: 0 0 14px;
}
.gate__btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  width: 100%;
  font-family: var(--font-body);
  font-size: 13px;
  font-weight: 500;
  padding: 12px 16px;
  background: #fff;
  border: 1px solid #d5d5d5;
  cursor: pointer;
}
.gate__btn:hover { background: #f7f7f7; }
.gate__btn:disabled { opacity: 0.6; cursor: default; }
.gate__note { font-size: 11px; color: var(--dim); margin: 18px 0 0; line-height: 1.7; }

.notice { font-size: 12px; padding: 9px 12px; margin: 0 0 16px; }
.notice--ok { background: #eaf4ec; color: #1c5c2c; }
.notice--err { background: #fdeceb; color: #8c1d18; }

/* dropzone */
.drop {
  background: #fff;
  border: 1px dashed #c9c9c9;
  padding: 34px 20px;
  text-align: center;
  cursor: pointer;
  margin-bottom: 14px;
  transition: border-color 0.15s, background 0.15s;
}
.drop:hover, .drop.is-over { border-color: var(--ink); background: #fbfbfb; }
.drop strong { display: block; font-size: 14px; margin-bottom: 4px; }
.drop span { font-size: 12px; color: var(--dim); }
.drop__prog {
  height: 3px;
  background: #ececec;
  margin-top: 16px;
  overflow: hidden;
}
.drop__prog i { display: block; height: 100%; width: 0; background: var(--ink); transition: width 0.2s; }

/* The "adding photos" panel is now instructions, not a drop target. */
.drop--static { cursor: default; background: #fcfcfc; border-style: solid; }
.drop--static:hover { border-color: var(--line); background: #fcfcfc; }
.drop__how {
  margin: 10px 0 0;
  font-size: 12.5px;
  line-height: 1.65;
  color: var(--dim);
  max-width: 68ch;
}
.drop__how code {
  font-size: 12px;
  background: #f1f1f1;
  padding: 1px 5px;
  border-radius: 2px;
}

/* card grid */
.cards {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(210px, 1fr));
  gap: 14px;
  margin-top: 6px;
}
.card { margin: 0; background: #fff; border: 1px solid var(--line); }
.card.is-hidden .card__img { opacity: 0.45; }
.card__img { position: relative; }
.card__img img { width: 100%; aspect-ratio: 4/5; object-fit: cover; }
.card__badge {
  position: absolute;
  top: 8px;
  left: 8px;
  font-size: 9px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  background: #fff;
  padding: 3px 7px;
}
.card.is-hidden .card__badge { background: #d8d8d8; }
.card__bar { padding: 9px; display: flex; flex-direction: column; gap: 8px; }
.card__alt {
  font-family: var(--font-body);
  font-size: 12px;
  padding: 6px 8px;
  border: 1px solid var(--line);
  width: 100%;
}
.card__alt:focus { outline: none; border-color: var(--ink); }
.card__acts { display: flex; gap: 5px; flex-wrap: wrap; }
.card__acts button {
  font-family: var(--font-body);
  font-size: 11px;
  padding: 4px 8px;
  background: #f4f4f4;
  border: 1px solid #e2e2e2;
  cursor: pointer;
  color: var(--ink);
}
.card__acts button:hover { background: #e9e9e9; }
.card__acts .is-danger { color: #b3261e; }

/* ---------------------------------------------------------- pricing */
/* Same restraint as the rest of the site: hairline rules, one heavy
   display size, no colour except the "most popular" flag. */

.pricing {
  max-width: 1180px;
  padding: 46px 0 90px;
}
.pricing__head { margin-bottom: 46px; max-width: 62ch; }
.pricing__h {
  font-family: var(--font-display);
  font-size: 40px;
  line-height: 0.9;
  letter-spacing: -0.03em;
  text-transform: uppercase;
  margin: 0 0 16px;
}
.pricing__intro { font-size: 14px; line-height: 1.7; color: var(--dim); margin: 0; }
.pricing__sub {
  font-family: var(--font-display);
  font-size: 15px;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  margin: 0 0 18px;
  padding-bottom: 10px;
  border-bottom: 1px solid var(--ink);
}

.pricing__grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: var(--gut);
  align-items: start;
}

.tier {
  position: relative;
  border: 1px solid var(--line);
  padding: 26px 22px 24px;
  background: #fff;
  display: flex;
  flex-direction: column;
  height: 100%;
}
.tier--pop { border-color: var(--ink); }
.tier__flag {
  position: absolute;
  /* `right: -1px` pushed the badge one full pixel past the card's border
     box, so it visibly overhung the edge. Sit it just inside instead. */
  top: 0;
  right: 0;
  background: var(--ink);
  color: #fff;
  font-size: 9px;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  padding: 5px 9px;
}
.tier__name {
  font-family: var(--font-display);
  font-size: 17px;
  letter-spacing: 0.01em;
  text-transform: uppercase;
  margin: 0 0 10px;
}
.tier__price {
  font-family: var(--font-display);
  font-size: 34px;
  line-height: 1;
  letter-spacing: -0.03em;
  margin: 0 0 4px;
}
.tier__spec {
  font-size: 11px;
  color: var(--dim);
  margin: 0 0 12px;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--line);
}
.tier__fit { font-size: 13px; line-height: 1.6; margin: 0 0 16px; }
.tier__list { list-style: none; margin: 0 0 22px; padding: 0; flex: 1; }
.tier__list li {
  position: relative;
  font-size: 12.5px;
  line-height: 1.55;
  padding-left: 15px;
  margin-bottom: 9px;
  color: #2a2a2a;
}
/* the tick is a hairline cross, not a glyph — matches the hairline rules */
.tier__list li::before {
  content: "";
  position: absolute;
  left: 0;
  top: 8px;
  width: 7px;
  height: 1px;
  background: var(--ink);
}
.tier__cta {
  display: block;
  text-align: center;
  border: 1px solid var(--ink);
  /* The CTA on every package card — a primary action, so it gets the same
     44px floor as the form button. */
  min-height: 44px;
  padding: 11px 12px;
  font-size: 12px;
  color: var(--ink);
  text-decoration: none;
  transition: background 0.15s, color 0.15s;
}
.tier__cta:hover { background: var(--ink); color: #fff; }
.tier--pop .tier__cta { background: var(--ink); color: #fff; }
.tier--pop .tier__cta:hover { background: #000; }

.pricing__addons, .pricing__terms { margin-top: 60px; }
.addons { list-style: none; margin: 0; padding: 0; }
.addons li {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  font-size: 13px;
  padding: 11px 0;
  border-bottom: 1px solid var(--line);
}
.addons__p { font-family: var(--font-display); font-size: 13px; white-space: nowrap; }

.terms { list-style: none; margin: 0 0 18px; padding: 0; max-width: 78ch; }
.terms li {
  font-size: 12.5px;
  line-height: 1.65;
  color: var(--dim);
  margin-bottom: 9px;
}
.pricing__note {
  font-size: 12.5px;
  line-height: 1.65;
  border-left: 2px solid var(--ink);
  padding-left: 14px;
  margin: 0;
  max-width: 78ch;
}

/* ------------------------------------------------------ responsive */

@media (max-width: 900px) {
  .contact { grid-template-columns: 1fr; gap: 36px; }
  .pricing__grid { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 640px) {
  :root { --head: 92px; --pad: 16px; --gut: 10px; }
  .site-header {
    grid-template-columns: 1fr auto;
    grid-template-areas: "logo social" "nav nav";
    align-content: center;
    row-gap: 10px;
  }
  .logo { grid-area: logo; }
  .site-nav { grid-area: nav; gap: 22px; }
  .site-social { grid-area: social; }
  .logo-lg { font-size: 21px; }
  .logo-sm { font-size: 10px; }
  .contact__h { font-size: 30px; }
  .pricing__h { font-size: 30px; }
  .pricing__grid { grid-template-columns: 1fr; }
  .tier__price { font-size: 30px; }
  .adm__bar { flex-wrap: wrap; }

  /* Tap targets are now handled in the BASE rules (min-height/min-width on
     .nav-link, .social, form fields, .tier__cta, .contact__list a), so they
     hold on tablet and desktop too. This block only pays for the extra
     padding with tighter gaps — the header must still fit 390px. */
  .nav-link { padding: 0 8px; }
  .site-nav { gap: 16px; }
  .site-social { gap: 8px; }

  /* Let the PAGE scroll on a phone. The desktop design gives each column its
     own scrollbar, which is the reference's signature look — but on touch it
     means the page itself is stationary, a nested scroll area fights the
     browser's own momentum, and the footer can be unreachable. That is the
     "laggy and not working well" feeling, and no amount of image weight
     fixes it. Normal document flow is what a phone expects. */
  .col {
    max-height: none;
    overflow: visible;
    /* The column is a flex column in a 1-col grid; nothing to scroll itself. */
    scroll-snap-type: none;
  }
  .cell { scroll-snap-align: none; }

  /* The grid gap was the only thing separating frames vertically; give the
     photo a little more air than the 10px mobile gutter. */
  .grid { gap: 12px; }
}

/* ------------------------------------------------- reduced motion */

/* The site animated 11 transitions and honoured none of them as optional.
 * None of it is decorative in the vestibular sense — no parallax, no large
 * translation, no autoplay — but that is not the test. prefers-reduced-motion
 * is set by people whose OS-level "reduce motion" is on, commonly for
 * migraine or vestibular disorder, and the polite reading is that a site
 * should still work if it stops moving.
 *
 * The blanket `*` is deliberate and is NOT a shortcut. These transitions are
 * declared at (0,1,0) and (0,2,0) across two files, and enumerating the
 * eleven elements would be a list that rots on the next edit — a new
 * transition would silently ship animated. `transition-duration: 0.01ms`
 * rather than `0s` is the standard incantation: 0s would also cancel
 * transition-delay, and a delayed transition is still a transition.
 *
 * Nothing here hides content or changes layout. The nav drawer and the burger
 * still open, the gallery still swaps, the upload progress bar still grows —
 * they just arrive at their final state immediately, which is what the
 * preference asks for. animation-duration is included so any future
 * @keyframes inherits the same guarantee. */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    transition-duration: 0.01ms !important;
    transition-delay: 0s !important;
    animation-duration: 0.01ms !important;
    animation-delay: 0s !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
  }

  /* The one place where a duration is load-bearing rather than decorative.
     .cell img fades in on load (opacity 0 -> 1); with the transition cut the
     frame appears at full opacity the moment it decodes, which is the desired
     outcome. The B&W reveal on hover is gated behind (hover: hover) already,
     so a touch device was never going to see it animate. */
  .shell.is-bw .cell img { filter: grayscale(1) contrast(1.06); }
}

/* --------------------------------------------------------- dark mode
   NOT IMPLEMENTED, on purpose. Recording the reasoning so it is not
   re-litigated every audit: this is a photography site, and the palette is
   --ink #111 on --paper #fff with photographs as the only colour in the
   document. Inverting that to a dark theme does not just swap two tokens —
   the hero scrim, the lightbox backdrop (#0c0c0c), the .cell placeholder
   grey and the white-on-photo header type are all tuned against a white
   page, and every ratio measured in this file was measured on it. Shipping
   a dark mode means re-deriving that whole set, and a plausible-looking
   inversion with unverified ratios is a worse outcome than a site that is
   honestly light-only. The monochrome brand carries over to a dark UI almost
   unchanged, so the design case is weak as well as the verification case.
   If it is ever wanted, the work is: re-run mobile-audit/a11y/contrast.py
   with a prefers-color-scheme: dark capture and hold the same thresholds. */

e:
/* =============================================================
   EDITORIAL LAYER — the 5-page reference design.

   Appended rather than merged into the tokens above: the existing chrome,
   gallery, lightbox and admin all pass their checks, and this layer only
   ADDS the new page classes plus the couple of overrides the reference needs.
   Anything that touches shared selectors is commented with why.

   Type note: the reference called for Playfair Display. Alwin's call was to
   keep Archivo Black for display, so the *shape* of the reference is carried
   by spacing, scale and rules instead of the serif.
   ============================================================= */

/* ------------------------------------------------------- shared type */

/* The small letterspaced label above every headline. In the reference this is
   Inter, 10px, +0.18em tracking, uppercase — deliberately quiet. */
.eyebrow {
  font-family: var(--font-body);
  font-size: 10.5px;
  font-weight: 500;
  letter-spacing: 0.19em;
  text-transform: uppercase;
  color: var(--ink);
  margin: 0 0 22px;
}

/* Page-level container. The reference runs a narrower measure on text pages
   than on the gallery, so this is a shared max-width with room to breathe. */
.page { padding: 0 0 var(--pad); }

/* --------------------------------------------------------- home hero */

/* On the home page the header floats ON the hero photograph, as in the
   reference — no white bar, white type, the picture running to the top edge.
   Scoped to the home route: a transparent header over a white page would be
   invisible, so the other pages keep their solid chrome. */
.shell--over .site-header {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  z-index: 5;
  /* No fill — the photograph IS the background. Only a top scrim, so white
     type stays legible over a bright sky without dulling the image.
     MEASURED, not guessed. The old stops were .45 -> 0 across the header's
     118px, which left the wordmark (measured at 2.49:1) and the burger bars
     (1.00:1 against a blown sky — white on white) failing WCAG. The stops
     below hold ~.66 through the 2.7%-10.6% band the wordmark occupies and
     .54 where the burger sits at 6.1%, then release to 0 so the scrim still
     ends inside the header. Verified at 6.69:1 and 15.52:1 across six
     frames including the gallery's brightest; see mobile-audit/a11y. */
  background: linear-gradient(180deg, rgba(0, 0, 0, 0.66) 0%, rgba(0, 0, 0, 0.54) 70%, rgba(0, 0, 0, 0) 100%);
}
.shell--over .nav-link { color: rgba(255, 255, 255, 0.82); }
.shell--over .nav-link:hover,
.shell--over .nav-link.is-active { color: #fff; }
.shell--over .nav-link.is-active { border-bottom-color: #fff; }
.shell--over .social { color: rgba(255, 255, 255, 0.85); }
.shell--over .social:hover { color: #fff; opacity: 1; }
/* The wordmark inherits colour, so it turns white with everything else. */
.shell--over .logo { color: #fff; }
/* Burger bars are background-coloured, so invert them here too. */
.shell--over .burger__bars i { background: #fff; }
/* The mobile drawer hangs over page content below, so it must stay solid. */
.shell--over .site-nav { color: var(--ink); }

/* Headline. Archivo Black is a single weight, so the "display" feel comes from
   tight leading and a generous size jump against the body text. */
.page h1,
.page h2,
.hero__h {
  font-family: var(--font-display);
  font-weight: 400;         /* Archivo Black ships 400; browsers fake anything else */
  line-height: 0.95;
  letter-spacing: -0.025em;
  text-transform: uppercase;
  margin: 0;
}

/* Body copy on the text pages — the reference sets it small and wide-tracked,
   which is what makes the type feel "small text / all caps" without caps. */
.prose { font-size: 14.5px; line-height: 1.72; color: var(--dim); }
.prose p { margin: 0 0 18px; }
.prose p:last-child { margin-bottom: 0; }

/* The reference's link treatment: a short em-dash, then the label, with a
   hairline that fills on hover. Used for every in-page CTA. */
.cta {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--ink);
  padding: 14px 0;
  min-height: 44px;
}
.cta::before {
  content: "";
  width: 26px;
  height: 1px;
  background: var(--ink);
  transition: width 0.18s ease;
}
.cta:hover::before { width: 40px; }
.cta--btn {
  border: 1px solid var(--ink);
  padding: 0 22px;
  min-height: 44px;
  background: var(--ink);
  color: #fff;
}
.cta--btn::before { display: none; }
.cta--btn:hover { background: #000; }

/* A page header block: eyebrow, headline, supporting line. */
.phead { max-width: 560px; padding: 40px 0 44px; }
.phead__h { font-size: clamp(38px, 6vw, 64px); }
.phead__p { margin: 26px 0 0; font-size: 14.5px; line-height: 1.72; color: var(--dim); max-width: 48ch; }
/* The frame count, replacing the category filter that used to sit here. */
.phead__count {
  margin: 14px 0 0;
  font-size: 10.5px;
  font-weight: 500;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--grey);
}

/* ------------------------------------------------------- home page */

.hero {
  position: relative;
  margin: 0 calc(-1 * var(--pad));
  min-height: min(78vh, 720px);
  display: flex;
  align-items: flex-end;
  overflow: hidden;
  background: #0d0d0d;
}
.hero__fig { position: absolute; inset: 0; margin: 0; }
/* `cover` fills the box, so a portrait source gets centre-cropped — which
   zooms into the middle of the frame and slices the subject's head off. Bias
   the crop to the upper third, where faces actually are, and let the scrim
   carry the bottom. */
.hero__fig img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  /* 0%, not 20%. The subject's head sits hard against the top of the SOURCE
     frame, so any downward bias clips her hair — measured across 0/6/12/20%,
     only 0% keeps the whole head with air above it. The cost is more sky and
     less floor; the scrim handles the bottom where the headline goes. */
  object-position: 50% 0%;
}
/* The headline sits on the photograph, so it needs a scrim to stay legible
   over a bright frame. A gradient, not a flat wash — the reference keeps the
   top of the image clean. */
.hero__scrim {
  position: absolute;
  inset: 0;
  /* The stop positions are PLACED, and the values are MEASURED.
     The old gradient ran .28 -> .12 at 38% -> .78 at 100%, and that .12 dip is
     the defect: the hero eyebrow sits at 35.9%-38% of the hero box, so the
     quietest part of the scrim landed exactly on the smallest, thinnest text
     on the page. Measured there, it was 1.36:1.

     The new shape keeps the 0%-22% falloff, because that is where the
     subject's face and the sky live and a dense wash there would dull the one
     thing the page exists to show. It then holds a plateau from 34% down,
     covering the eyebrow (36-38%), the headline (41-62%), the lede (67-75%)
     and the meta strip (93-100%).

     Values came from a sweep, not from taste: candidates were injected into
     the live page, painted, captured and decoded against the gallery's
     brightest frame. This shape measures 5.60:1 on that worst case (a
     1.24:1 before) and 5.70:1-8.45:1 across the other five. The scrim is
     still not opaque: the photograph reads through it, which is checked by
     eye as well as by ratio. */
  background: linear-gradient(180deg, rgba(0, 0, 0, 0.36) 0%, rgba(0, 0, 0, 0.12) 22%, rgba(0, 0, 0, 0.62) 34%, rgba(0, 0, 0, 0.66) 40%, rgba(0, 0, 0, 0.70) 66%, rgba(0, 0, 0, 0.76) 80%, rgba(0, 0, 0, 0.86) 100%);
  pointer-events: none;
}
.hero__body {
  position: relative;
  z-index: 1;
  /* 96px of bottom padding clears the .hero__meta strip pinned underneath. */
  padding: 0 var(--pad) 96px;
  /* No width cap: the heading is now up to 132px and "PORTRAITURE" measures
     ~810px there, far past the old 720px (and before that 640px) caps, each of
     which the audit reported as clipped text. The lede keeps its own 40ch. */
  max-width: 100%;
  color: #fff;
  width: 100%;
}
.hero__body .eyebrow {
  color: #fff;
  opacity: 0.9;
  font-family: var(--font-mono);
  font-weight: 400;
  font-size: 11px;
  letter-spacing: 0.14em;
  margin-bottom: 18px;
}
/* 86px -> up to 132px, tighter leading and tracking. The old size was polite for
   a brutalist site, and the lede sat almost on top of the last line; the 34px
   margin is what separates them now. */
.hero__h { font-size: clamp(48px, 9.6vw, 132px); }
/* Specificity matters here: `.page h1` (0,1,1) sets margin:0, line-height and
   letter-spacing and beats a bare `.hero__h` (0,1,0). That is why the old
   `margin-bottom: 24px` never applied and the lede sat flush under the heading.
   `.page .hero__h` (0,2,0) wins. */
.page .hero__h {
  line-height: 0.88;
  letter-spacing: -0.035em;
  margin-bottom: 34px;
}
/* The negative tracking pulls the final glyph past the text box, so
   "PORTRAITURE" reports scrollWidth > clientWidth and reads as clipped.
   Absorb it with padding on the heading itself rather than losing the
   tracking — padding on .hero__body would not widen the h1's own box. */
.hero__h { padding-right: 0.06em; } /* was .05em; tracking is tighter now */
/* Same overflow on the HERO heading, where the box is capped by max-width on
   the parent. Let the heading size to its own text so the negative tracking
   has no box to exceed: `width: max-content` + wrapping for narrow screens. */
@media (min-width: 900px) {
  /* 7.5em forces "Timeless / Portraiture" onto two lines now the body has no
     width cap: "Portraiture" is ~6.3em wide, the full title ~10.6em. */
  .hero__h { width: max-content; max-width: min(100%, 7.5em); }
}
/* On a phone the longest word is wider than the column, so it has to be
   allowed to break rather than overflow. `overflow-wrap: anywhere` is the
   only value that breaks INSIDE a word; `break-word` still lets a single
   long word exceed the box. */
@media (max-width: 640px) {
  .hero__h { overflow-wrap: anywhere; }
}

/* Bottom strip: founding year + place, the three subjects, a scroll cue.
   Real text from config (home.est, home.tags, contact.location), not decoration. */
.hero__meta {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 2;
  display: flex;
  justify-content: space-between;
  gap: 16px;
  padding: 14px var(--pad) 16px;
  border-top: 1px solid rgba(255, 255, 255, 0.45);
  color: #fff;
  font: 11px/1 var(--font-mono);
  letter-spacing: 0.12em;
  text-transform: uppercase;
}
.hero__meta span { white-space: nowrap; }

.hero__lede {
  margin: 0 0 30px;
  font-size: 15px;
  line-height: 1.7;
  max-width: 40ch;
  opacity: 0.92;
}
.hero__body .cta { color: #fff; }
.hero__body .cta::before { background: #fff; }

/* Selected-work strip under the hero.
 *
 * The section went through three layouts, and only the third is balanced:
 *
 *  1. A plain 3-col GRID — every row took the height of its tallest cell, so
 *     short frames got letterboxed into dead space. Alwin: "spaces shitty."
 *  2. CSS `columns` — packed tight, but it fills strictly top-to-bottom, so
 *     8 frames became 3/3/2 and the third column ended 379px short at 1440 and
 *     183px short at 390. Alwin: "slides seem uneven."
 *  3. This one — real column divs filled by `packByHeight()`, which places
 *     each frame in whichever column is currently shortest. The ragged bottom
 *     is gone and the packing is still tight.
 *
 * The column count arrives as `--strip-cols` from the same `cols` value the
 * portfolio wall uses, so both agree at every viewport.
 */
.hstrip { padding: 72px 0 0; }
/* Header row: hairline, label left, count right. Replaces the 10px floating
   eyebrow. The packed columns below are NOT touched. */
.hstrip__head {
  display: flex;
  justify-content: space-between;
  border-top: 1px solid var(--ink);
  padding-top: 12px;
  margin-bottom: 22px;
  font: 11px/1 var(--font-mono);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--ink);
}


.hstrip__grid {
  display: grid;
  /* Explicit count, set inline as `--strip-cols` from the same value the JS
   * used to emit the columns. `auto-fit` does NOT infer a track per child, and
   * `grid-auto-flow: column` flows items into ROWS — which stacks the columns
   * vertically. One source of truth: `stripCols()` in pages.ts. */
  grid-template-columns: repeat(var(--strip-cols, 3), minmax(0, 1fr));
  gap: var(--gut);
  margin-bottom: 14px;
}
.hstrip__col { display: flex; flex-direction: column; gap: var(--gut); }
.hstrip__col .cell { margin: 0; }
/* Closing band — flush-left like the rest of the site, with the entry price
   and one contact line. See homeBand() in pages.ts for why. */
.hcta {
  margin: 88px calc(-1 * var(--pad)) 0;
  padding: 72px var(--pad) 0;
  background: #0d0d0d;
  color: #fff;
  text-align: left;
}
.hcta__grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr;
  gap: 48px;
