}
/* max-width in ch makes "Capture What Matters." break onto three lines at any
   viewport instead of relying on a hard <br>, so the heading stays editable. */
.hcta__h { font-size: clamp(48px, 8.4vw, 118px); max-width: 9ch; }
.page .hcta__h { line-height: 0.9; letter-spacing: -0.035em; margin: 0; } /* beats `.page h2` */
.hcta__k {
  margin: 0 0 12px;
  font: 11px/1 var(--font-mono);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  opacity: 0.7;
}
.hcta__price {
