/* ------------------------------------------------------- mobile */

@media (max-width: 760px) {
  .burger { display: flex; }

  /* The desktop template is `1fr auto 1fr` (3 cells) but mobile has FOUR
     children — logo, burger, nav, socials — so the burger wrapped onto a second
     grid row and pushed the header 44px taller. Rebalance to THREE tracks on
     mobile, with the nav pulled out of flow to become the drawer:
        logo | burger | socials
     The burger sits centre and the socials pin right, which keeps the same
     visual order the reference shows on a phone. */
  .site-header {
    grid-template-columns: 1fr auto 1fr;
    grid-template-areas: "logo burger social" "nav nav nav";
  }
  .logo { grid-area: logo; }
  .burger { grid-area: burger; align-self: center; }
  .site-social { grid-area: social; justify-self: end; }
  .site-nav { grid-area: nav; }

  /* The nav becomes a full-width drawer under the header. Kept in the DOM and
     just visually collapsed so the toggle can animate it; `visibility` keeps
     it out of the tab order when closed, which `display:none` alone would too
     but without the transition. */
  .site-nav {
    position: absolute;
    top: 100%;
    left: 0;
    right: 0;
    /* The drawer must sit ABOVE the page on every route.
     *
     * It had no z-index, and only `shell--over` (the home page) gave its header
     * one. So on every other route the open drawer was painted UNDER the page
     * content. Measured on #/portfolio at 390px with the drawer open: the "About"
     * link reports the element at its centre as an <img class="is-loaded"> — the
     * photo grid was covering the menu. Alwin: "when I open the menu in portfolio
     * it doesnt show same things as home", and correctly so: Home, Portfolio,
     * About, Services and Contact were ALL in the DOM the whole time, but only
     * the first two were visible. The rest sat behind photographs.
     *
     * The header is the containing block, so raising the header is what carries
     * the drawer with it. 5 is the value shell--over already used, so the two
     * routes now stack identically. */
    z-index: 5;
    flex-direction: column;
    gap: 0;
    background: var(--paper);
    border-bottom: 1px solid var(--line);
    padding: 6px var(--pad) 14px;
    visibility: hidden;
    opacity: 0;
    transform: translateY(-6px);
    transition: opacity 0.16s ease, transform 0.16s ease, visibility 0.16s;
  }
  .site-nav.is-open { visibility: visible; opacity: 1; transform: none; }

  /* Scrim behind the open drawer, plus the scroll lock — added 2026-10-02.
     *
     * Two defects, one cause: there was no scrim, so there was no "outside" to
     * tap. On #/contact a tap at (196,600) landed on the TEXTAREA with
     * aria-expanded still "true", and dragging the open drawer scrolled the
     * background 800 -> 985px underneath. The `nav-open` class main.ts has been
     * setting since day one was styled NOWHERE, which is why the scroll lock
     * never existed.
     *
     * Fixed viewport height in the `top`/`height` pair rather than `100%`, so
     * the scrim covers the visible screen even when the document is taller and
     * the iOS URL bar has collapsed. Below the header (var(--head)) so it never
     * covers the burger or the wordmark. */
  .nav-scrim {
    position: fixed;
    top: var(--head);
    left: 0;
    right: 0;
    height: 100vh;
    background: rgba(17, 17, 17, 0.34);
    opacity: 0;
    transition: opacity 0.16s ease;
    /* Above the page content, below the drawer (z 5) and the sticky header
       (z 6), so it dims the photographs without touching the menu. */
    z-index: 4;
  }
  body.nav-open .nav-scrim { opacity: 1; }

  /* Stop the page behind the drawer moving. `overflow: hidden` on the root is
     what actually stops iOS Safari rubber-banding the background. */
  html.nav-locked,
  html.nav-locked body { overflow: hidden; }

  /* The home page is the only route with `shell--over`, which paints .nav-link
     WHITE for the transparent header sitting on the hero photograph. The drawer
     below it is painted `var(--paper)` — solid white — so those white links land
     on a white background and all five become invisible.

     Measured before this fix, home only:
         Home 1:1  Portfolio 1:1  About 1:1  Services 1:1  Contact 1:1
     and on every other route:
         5.33:1 inactive, 18.88:1 active

     The intent was already half-stated above the rule (".shell--over .site-nav {
     color: var(--ink) }") but setting `color` on the PARENT cannot beat a rule
     that sets `color` on the .nav-link itself at the same specificity. So the
     child won and the correction never applied. It has to be set on the link.

     The logo and the burger bars stay white: they sit in the transparent header
     over the photograph, not in the drawer. Only the drawer's links change. */
  /* Inactive links take the SAME grey as every other route. An earlier version
     of this rule used --ink, which made the home drawer the only one with black
     inactive links — measured side by side:
         home      rgb(17,17,17)   <- too dark, wrong
         portfolio rgb(107,107,107) <- the site's own inactive grey
     --grey is what the rest of the site uses, so home follows it rather than the
     other way round. Active and hover stay --ink, as everywhere else. */
  .shell--over .nav-link { color: var(--grey); }
  .shell--over .nav-link:hover { color: var(--ink); }
  .shell--over .nav-link.is-active,
  .shell--over .nav-link.is-active:hover { color: var(--ink); }
  .shell--over .nav-link.is-active { border-bottom-color: var(--ink); }
  .nav-link {
    display: block;
    padding: 15px 0;
    border-bottom: 1px solid var(--line);
    font-size: 12px;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    min-height: 44px;
  }
  .nav-link:last-child { border-bottom: 0; }
  .nav-link.is-active { border-bottom-color: var(--ink); }
}

/* The reference says "do not simply shrink the desktop design" — these are
   real recompositions, not a scaled-down desktop. */
@media (max-width: 1000px) {
  .about, .ct { grid-template-columns: 1fr; gap: 44px; }
  .invest { grid-template-columns: 1fr; gap: 24px; }
  .shead { grid-template-columns: 1fr; gap: 26px; }
  .pkgrow { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .ct__fig { order: -1; }
  .ct__fig img { aspect-ratio: 16 / 10; }
}

@media (max-width: 760px) {
  .pkgrow { grid-template-columns: 1fr; gap: 44px; }
  .invest, .hcta { margin-left: calc(-1 * var(--pad)); margin-right: calc(-1 * var(--pad)); }
}

@media (max-width: 640px) {
  /* The header must be at least as tall as its tallest child. 74px was
     below the 49px logo plus the burger's 44px row once `align-items: center`
     measured against a FIXED height — the grid row came out 48.6px, so the
     logo was centred inside a box 0.4px smaller than itself and pushed to
     top: -14.3px, taking "SHUTTERHAUS" off-screen again. `min-height`
     lets the row grow to fit instead. */
  :root { --pad: 18px; --head: 92px; }
  /* --sat is ADDED to the 10px top pad, not replacing it: this rule overrides
     the desktop `padding: var(--sat) var(--pad) 0` wholesale, so dropping the
     inset here would put the burger back under the Dynamic Island on exactly
     the viewport where the burger is the only navigation. min-height grows
     with the inset for the same reason `height` is not used here. */
  .site-header { height: auto; min-height: calc(var(--head) + var(--sat)); padding: calc(10px + var(--sat)) var(--pad) 10px; }

  .hero { min-height: 72vh; }
  .hero__body { padding-bottom: 80px; }
  .hero__lede { font-size: 14px; }
  /* Phone width fits one line of meta: keep the year and place, drop the rest. */
  .hero__meta-tags, .hero__meta-cue { display: none; }
  .phead { padding: 28px 0 32px; }
  .hcta { padding: 54px var(--pad) 0; }
  .hcta__grid { grid-template-columns: 1fr; gap: 36px; padding-bottom: 48px; }
  .hcta__foot span { display: none; }
  .invest { padding: 40px var(--pad) 44px; }

  .about__body, .ct__col { padding-top: 28px; }
}

/* ---------------------------------------------------- static wall, 10 rows
 *
 * Alwin, 2026-10-01: no per-column scroll, static, no numbering, 30 of the best,
 * 3 per row, "no spacing issues at all".
 *
 * `.pf-row` is a plain 3-column grid. No max-height, no overflow, no mask, no
 * wheel handler: nothing here scrolls, so a stray rule elsewhere cannot make it.
 *
 * The evenness comes from the DATA, not from here — every row in src/rows.ts
 * holds three frames of the exact same aspect ratio, so at a fixed column width
 * the three are the same height and there is no gap under any of them. CSS
 * `align-items: stretch` is the default and is left alone: stretch cannot change
 * an image's height here because the grid row is sized by the tallest item and
 * all three are equal, so the cells are already equal.
 *
 * `align-items: start` is set anyway, deliberately. If a future pick breaks the
 * ratio guarantee, stretch would make a short photo look TALLER (letterboxed
 * whitespace) instead of leaving a visible gap, which hides the fault. `start`
 * surfaces it.
 */
.pf-rows {
  display: flex;
  flex-direction: column;
  gap: var(--gut);
}
.pf-row {
  display: grid;
  /* Follows the inline --row-cols that pages.ts already computes from the
     measured row width. This was hardcoded to repeat(3, …) at every viewport
     while a comment said the variable was "deliberately NOT used" — the
     variable was dead, and the wall rendered 111px tiles on a 393px phone, too
     narrow to read a face. wallCols() emits 2 there and the CSS now obeys. */
  grid-template-columns: repeat(var(--row-cols, 2), minmax(0, 1fr));
  gap: var(--gut);
  align-items: start;
}
.pf-row .cell,
.pf-row .cell picture,
.pf-row .cell img {
  display: block;
  width: 100%;
  height: auto;
}
/* Two per row on a phone. This is now safe because every row in src/rows.ts
   holds exactly TWO frames, so reducing the columns does not push a cell onto
   its own line — which is what made three-per-row impossible to reflow. */
@media (max-width: 760px) {
  .pf-row { gap: 12px; }
  .pf-rows { gap: 12px; }
}

/* Booking-terms block headings.
 *
 * `.sterms`, `.sterms__h` and `.sterms--terms` had NO rule anywhere, so the
 * headings inherited `.page h2`'s `margin: 0` and sat flush against the lines
 * beneath them. Measured on #/services before this change:
 *     "Add-ons"       margin-bottom 0px, gap to next element 0px
 *     "Booking terms"  margin-bottom 0px, gap to next element 0px
 * A 24px display heading with zero gap below it reads as a mis-typed line.
 *
 * ONLY the margin is set here. An earlier attempt at this also shrank the
 * heading to 11px and swapped it out of the display face — a restyle nobody
 * asked for, and the heading was not broken, only tight. Typography is left
 * exactly as `.page h2` defines it.
 *
 * The `.page` prefix is required: `.page h2` (0,1,1) sets margin: 0 and would
 * beat a bare `.sterms__h` (0,1,0) — the same trap as `.about__h`. */
.page .sterms__h { margin-bottom: 16px; }
.sterms + .sterms { margin-top: 28px; }

/* Same story on the contact page: `.contact__h` had no margin-bottom, so the
 * 40px title sat 14px above the first paragraph. */
.page .contact__h { margin-bottom: 20px; }
